'use strict';
const assert = require('node:assert/strict');
const createRouteTable = require('./solution');
assert.equal(typeof createRouteTable, 'function');

const wildcard = { kind: 'wildcard' };
const exactFirst = { kind: 'exact-first' };
const exactSecond = { kind: 'exact-second' };
const getOther = { kind: 'other' };
const routes = [
  { method: 'GET', path: '*', handler: wildcard },
  { method: 'GET', path: '/items', handler: exactFirst },
  { method: 'GET', path: '/items', handler: exactSecond },
  { method: 'GET', path: '/other', handler: getOther },
  { method: 'POST', path: '*', handler: undefined }
];
const table = createRouteTable(routes);
assert.equal(typeof table.resolve, 'function');
assert.strictEqual(table.resolve('GET', '/items'), exactFirst);
assert.strictEqual(table.resolve('GET', '/other'), getOther);
assert.strictEqual(table.resolve('GET', '/missing'), wildcard);
assert.strictEqual(table.resolve('POST', '/anything'), undefined);
assert.strictEqual(table.resolve('DELETE', '/items'), null);

routes[0].handler = 'changed';
routes[1].path = '/changed';
routes.push({ method: 'GET', path: '/later', handler: 'later' });
assert.strictEqual(table.resolve('GET', '/items'), exactFirst);
assert.strictEqual(table.resolve('GET', '/missing'), wildcard);
assert.strictEqual(table.resolve('GET', '/later'), wildcard);
const empty = createRouteTable([]);
assert.strictEqual(empty.resolve('GET', '/x'), null);

assert.throws(() => createRouteTable(null), TypeError);
assert.throws(() => createRouteTable([null]), TypeError);
assert.throws(() => createRouteTable([[]]), TypeError);
assert.throws(() => createRouteTable([{ method: '', path: '/', handler: 1 }]), TypeError);
assert.throws(() => createRouteTable([{ method: 'get', path: '/', handler: 1 }]), TypeError);
assert.throws(() => createRouteTable([{ method: 'GET', path: 'x', handler: 1 }]), TypeError);
assert.throws(() => createRouteTable([{ method: 'GET', path: '/' }]), TypeError);
assert.throws(() => table.resolve('get', '/x'), TypeError);
assert.throws(() => table.resolve('', '/x'), TypeError);
assert.throws(() => table.resolve('GET', 'x'), TypeError);
assert.throws(() => table.resolve('GET', 1), TypeError);

